mapper.select:
SELECT
    (
        SELECT COUNT(*)
        FROM bookings b
        JOIN schedules s ON b.schedule_id = s.schedule_id
        WHERE s.aircraft_id = #{aircraftId}
          AND b.is_deleted = FALSE
          AND b.status != #{bookingCancelledStatus}
    ) AS activeBookingCount,
    (
        SELECT COUNT(*)
        FROM schedules
        WHERE aircraft_id = #{aircraftId}
          AND status != #{scheduleCancelledStatus}
    ) AS activeScheduleCount,
    (
        SELECT COUNT(*)
        FROM schedule_templates
        WHERE aircraft_id = #{aircraftId}
    ) AS scheduleTemplateCount
